from functools import wraps
import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    cache = {}
    last_access = {}

    def memoized_func(*args, **kwargs):
        key = (args, tuple(sorted(kwargs.items())) if typed else args)
        if key in cache and timer() - last_access[key] < ttl:
            return cache[key]
        else:
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                oldest_key = min(cache, key=lambda x: last_access[x])
                del cache[oldest_key]
                del last_access[oldest_key]
            cache[key] = result
            last_access[key] = timer()
            return result

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            return memoized_func(*args, **kwargs)
        return wrapper

    return decorator
