def difference(d1, d2, level=-1):
    if level == -1:  # infinite recursion
        result = {}
        for key in d1:
            if key in d2:
                if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                    result[key] = difference(d1[key], d2[key], level=-1)
                elif d1[key] != d2[key]:
                    result[key] = d1[key]
            else:
                result[key] = d1[key]
        return result
    elif level > 0:  # non-infinite recursion, recursive level limit
        result = {}
        for key in d1:
            if key in d2:
                if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                    result[key] = difference(d1[key], d2[key], level=level-1)
                elif d1[key] != d2[key]:
                    result[key] = d1[key]
            else:
                result[key] = d1[key]
        return result
    else:
        raise ValueError("Invalid level argument. Level must be -1 or a positive integer")
