def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    self.inventory = {}
    self.content_digests = {}

    for version_dir in version_dirs:
        version_inventory = self.get_inventory(version_dir)
        for manager in version_inventory:
            action, location, content = manager.action, manager.location, manager.content
            if manager.action == 'Add':
                if location not in self.inventory:
                    self.inventory[location] = []
                self.inventory[location].append((content.content, content.digest))
            elif manager.action == 'Modify':
                if location not in self.inventory:
                    raise ValueError(f"No inventory for {location} in version {version_dir}")
                for item in self.inventory[location]:
                    if item[0] == content.content:
                        item[1] = content.digest
                        break
                else:
                    raise ValueError(f"No content to modify in {location} in version {version_dir}")
            elif manager.action == 'Delete':
                if location not in self.inventory:
                    raise ValueError(f"No inventory for {location} in version {version_dir}")
                for item in self.inventory[location]:
                    if item[0] == content.content:
                        self.inventory[location].remove(item)
                        break
                else:
                    raise ValueError(f"No content to delete in {location} in version {version_dir}")

    for version_dir in version_dirs:
        version_inventory = self.get_inventory(version_dir)
        for location, items in version_inventory.items():
            if location not in self.content_digests:
                self.content_digests[location] = {}
            for item, digest in items:
                if item not in self.content_digests[location]:
                    self.content_digests[location][item] = digest
                elif self.content_digests[location][item] != digest:
                    raise ValueError(f"Content digest mismatch for {location} in version {version_dir}")
