def parse_arguments(*unparsed_arguments):
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers()

    # Default subparser for global arguments
    global_parser = subparsers.add_parser('global')
    global_parser.set_defaults(func=lambda _: global_parser.parse_args())

    # Specific subparser for specific argument
    specific_parser = subparsers.add_parser('specific')
    specific_parser.set_defaults(func=lambda specific_args: specific_parser.parse_args(specific_args))

    unique_subparsers = {subparser.name: subparser for subparser in subparsers}
    args, unparsed_args = parser.parse_known_args(unparsed_arguments)

    if args.func:
        parsed_arguments = {args.func.__name__: args}
        parsed_arguments.update({subparser_name: subparser.parse_args() for subparser_name, subparser in unique_subparsers.items() if subparser_name != args.func.__name__ and not subparser_name.startswith('global')})
    else:
