from datetime import timedelta

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    freq_parts = frequency.split()
    if len(freq_parts) != 2:
        raise ValueError(" Invalid frequency format. Should be 'number unit' (e.g., '3 weeks').")

    number, unit = freq_parts
    if not number.isdigit():
        raise ValueError("Number part is not a valid integer.")

    unit_to_seconds = {
        's': 1,
        'm': 60,
        'h': 3600,
        'd': 86400,
        'w': 604800
    }

    try:
        seconds = int(number) * unit_to_seconds[unit]
        return timedelta(seconds=seconds)
    except KeyError:
        raise ValueError(f"Unknown unit: {unit}")
